  3395	                        Ok(response) if response.ok => response,
  3396	                        Ok(response) => {
  3397	                            let error = response.error.unwrap_or_else(|| "unknown error".into());
  3398	                            self.status
  3399	                                .set(format!("session load failed: {}", concise_error(&error)));
  3400	                            return;
  3401	                        }
  3402	                        Err(error) => {
  3403	                            log::warn!("projection snapshot decode failed: {error}");
  3404	                            if attempt + 1 == PROJECTION_RETRIES {
  3405	                                self.status.set("session projection decode failed".into());
  3406	                                return;
  3407	                            }
  3408	                            gloo_timers::future::TimeoutFuture::new(75).await;
  3409	                            continue;
  3410	                        }
  3411	                    }
  3412	                }
  3413	                Ok(response) => {
  3414	                    let text = response.text().await.unwrap_or_default();
  3415	                    if !self.projection_generation_is_current(&id, generation) {
  3416	                        return;
  3417	                    }
  3418	                    self.status
  3419	                        .set(format!("session load failed: {}", concise_error(&text)));
  3420	                    return;
  3421	                }
  3422	                Err(error) => {
  3423	                    if attempt + 1 == PROJECTION_RETRIES {
  3424	                        self.status.set(format!(
  3425	                            "session load failed: {}",
  3426	                            concise_error(&error.to_string())
  3427	                        ));
  3428	                        return;
  3429	                    }
  3430	                    gloo_timers::future::TimeoutFuture::new(75).await;
  3431	                    continue;
  3432	                }
  3433	            };
