  2533	        spawn_local(async move {
  2534	            loop {
  2535	                if sse_generation.get_untracked() != generation {
  2536	                    break;
  2537	                }
  2538	                clear_stream_marker(permission_stream_ready, &active_session_id, generation);
  2539	                set_stream_source(
  2540	                    &planner_stream_sources,
  2541	                    &active_session_id,
  2542	                    generation,
  2543	                    true,
  2544	                    None,
  2545	                );
  2546	                let events_url = format!("{}/v1/events", url.trim_end_matches('/'));
  2547	                let mut es = match EventSource::new(&events_url) {
  2548	                    Ok(es) => es,
  2549	                    Err(_) => {
  2550	                        gloo_timers::future::TimeoutFuture::new(2_000).await;
  2551	                        continue;
  2552	                    }
  2553	                };
  2554	
  2555	                let mut subs = Vec::new();
  2556	                let mut sub_err = false;
  2557	                for name in ["permission_request", "permission_decision"] {
  2558	                    match es.subscribe(name) {
  2559	                        Ok(s) => subs.push(s),
  2560	                        Err(_) => {
