  3362	    fn restart_projection(&self, id: &str, generation: u64, reason: &str) {
  3363	        if !self.projection_generation_is_current(id, generation) {
  3364	            return;
  3365	        }
  3366	        log::warn!("restarting session projection for {id}: {reason}");
  3367	        let next = generation.wrapping_add(1);
  3368	        self.sse_generation.set(next);
  3369	        self.planner_stream_sources
  3370	            .borrow_mut()
  3371	            .reset(id.to_string(), next);
  3372	        self.status.set("resyncing session…".into());
  3373	        self.spawn_projection_sync(id.to_string(), next);
  3374	    }
