  3663	                Ok(stream) => stream,
  3664	                Err(error) => {
  3665	                    daemon.restart_projection(
  3666	                        &id,
  3667	                        generation,
  3668	                        &format!("tail subscribe failed: {error}"),
  3669	                    );
  3670	                    return;
