2522	    /// server-side, so we drop any frame whose envelope `session_id` isn't ours.
2523	    /// When gating is off the daemon never emits these, so this stream just sits
2524	    /// idle — no behavior change for the ungated path.
2525	    fn connect_permission_stream(&self, active_session_id: String, generation: u64) {
2526	        let url = self.url.get_untracked();
2527	        let sse_generation = self.sse_generation;
2528	        let permission_stream_ready = self.permission_stream_ready;
2529	        let permission_revision = self.permission_revision;
2530	        let planner_stream_sources = self.planner_stream_sources.clone();
2531	        let pending = self.pending_permissions;
2532	
2533	        spawn_local(async move {
2534	            loop {
2535	                if sse_generation.get_untracked() != generation {
2536	                    break;
2537	                }
2538	                clear_stream_marker(permission_stream_ready, &active_session_id, generation);
2539	                set_stream_source(
2540	                    &planner_stream_sources,
2541	                    &active_session_id,
2542	                    generation,
2543	                    true,
2544	                    None,
2545	                );
2546	                let events_url = format!("{}/v1/events", url.trim_end_matches('/'));
2547	                let mut es = match EventSource::new(&events_url) {
2548	                    Ok(es) => es,
2549	                    Err(_) => {
2550	                        gloo_timers::future::TimeoutFuture::new(2_000).await;
2551	                        continue;
2552	                    }
2553	                };
2554	
2555	                let mut subs = Vec::new();
2556	                let mut sub_err = false;
2557	                for name in ["permission_request", "permission_decision"] {
2558	                    match es.subscribe(name) {
2559	                        Ok(s) => subs.push(s),
2560	                        Err(_) => {
2561	                            sub_err = true;
2562	                            break;
2563	                        }
2564	                    }
2565	                }
2566	                if sub_err {
2567	                    gloo_timers::future::TimeoutFuture::new(2_000).await;
2568	                    continue;
2569	                }
2570	
2571	                if !await_event_source_open(&es).await {
2572	                    continue;
2573	                }
2574	                permission_stream_ready.set(stream_marker_for_state(
2575	                    es.state(),
2576	                    &active_session_id,
2577	                    generation,
2578	                ));
2579	                set_stream_source(
2580	                    &planner_stream_sources,
2581	                    &active_session_id,
2582	                    generation,
2583	                    true,
2584	                    Some(es.clone()),
2585	                );
3280	        let daemon = self.clone();
3281	        model.set(Some(id.clone()));
3282	        spawn_local(async move {
3283	            let post_url = format!("{}/v1/model", url.trim_end_matches('/'));
3284	            let body = serde_json::json!({ "model": id });
3285	            match Request::post(&post_url)
3286	                .header("content-type", "application/json")
3287	                .json(&body)
3288	            {
3289	                Ok(req) => match req.send().await {
3290	                    Ok(_) => {
3291	                        // Confirm the authoritative selection.
3292	                        daemon.fetch_models();
3293	                    }
3294	                    Err(err) => {
3295	                        let raw = err.to_string();
3296	                        log::error!("model swap error: {raw}");
3297	                        status.set(format!("model swap error: {}", concise_error(&raw)));
3298	                    }
3299	                },
3300	                Err(err) => {
3301	                    let raw = err.to_string();
3302	                    log::error!("model encode error: {raw}");
3303	                    status.set(format!("model encode error: {}", concise_error(&raw)));
3304	                }
3305	            }
3306	        });
3307	    }
