3335	    /// Switch with an atomic daemon-owned projection attach. Every old transport
3336	    /// is closed before the GET begins; the canonical snapshot and retained
3337	    /// frames are installed as one batch before either live tail is opened.
3338	    pub fn switch_session(&self, id: String, title: String) {
