3376	    async fn sync_session_projection(&self, id: String, generation: u64) {
3377	        const PROJECTION_RETRIES: usize = 4;
3378	        for attempt in 0..PROJECTION_RETRIES {
3379	            if !self.projection_generation_is_current(&id, generation) {
3380	                return;
3381	            }
3382	            let url = self.url.get_untracked();
3383	            let get_url = format!("{}/v1/sessions/{id}", url.trim_end_matches('/'));
3384	            let fetched = Request::get(&get_url).send().await;
3385	            if !self.projection_generation_is_current(&id, generation) {
3386	                return;
3387	            }
3388	            let response = match fetched {
3389	                Ok(response) if response.ok() => {
3390	                    let decoded = response.json::<SessionDetailResponse>().await;
3391	                    if !self.projection_generation_is_current(&id, generation) {
3392	                        return;
3393	                    }
3394	                    match decoded {
3395	                        Ok(response) if response.ok => response,
3396	                        Ok(response) => {
3397	                            let error = response.error.unwrap_or_else(|| "unknown error".into());
3398	                            self.status
3399	                                .set(format!("session load failed: {}", concise_error(&error)));
3400	                            return;
3401	                        }
3402	                        Err(error) => {
3403	                            log::warn!("projection snapshot decode failed: {error}");
3404	                            if attempt + 1 == PROJECTION_RETRIES {
3405	                                self.status.set("session projection decode failed".into());
3406	                                return;
3407	                            }
3408	                            gloo_timers::future::TimeoutFuture::new(75).await;
3409	                            continue;
3410	                        }
3411	                    }
3412	                }
3413	                Ok(response) => {
3414	                    let text = response.text().await.unwrap_or_default();
3415	                    if !self.projection_generation_is_current(&id, generation) {
3416	                        return;
3417	                    }
3418	                    self.status
3419	                        .set(format!("session load failed: {}", concise_error(&text)));
3420	                    return;
3421	                }
3422	                Err(error) => {
3423	                    if attempt + 1 == PROJECTION_RETRIES {
3424	                        self.status.set(format!(
3425	                            "session load failed: {}",
3426	                            concise_error(&error.to_string())
3427	                        ));
3428	                        return;
3429	                    }
3430	                    gloo_timers::future::TimeoutFuture::new(75).await;
3431	                    continue;
3432	                }
3433	            };
3434	            if !self.projection_generation_is_current(&id, generation) {
3435	                return;
3436	            }
3437	            let Some(detail) = response.session else {
3438	                self.status.set("session snapshot missing".into());
3439	                return;
3440	            };
3441	            if detail.id != id {
3442	                self.restart_projection(&id, generation, "snapshot session mismatch");
3443	                return;
3444	            }
3445	
3446	            match response.projection {
3447	                Some(projection) => match prepare_projection_snapshot(detail, projection) {
3448	                    Ok(prepared) => {
3449	                        if !self.install_projection_snapshot(&id, generation, prepared) {
3450	                            return;
3451	                        }
3452	                        return;
3453	                    }
3454	                    Err(ProjectionPreparation::Restart | ProjectionPreparation::Invalid) => {
3455	                        if attempt + 1 == PROJECTION_RETRIES {
3456	                            self.restart_projection(
3457	                                &id,
3458	                                generation,
3459	                                "invalid or refetch projection frame",
3460	                            );
3461	                            return;
3462	                        }
3463	                    }
3464	                },
3465	                None if detail.persistence_revision.is_none() => {
3466	                    // Explicit old-daemon path. The complete hydrate precedes
3467	                    // connect(), preserving the legacy best-effort ordering.
3468	                    if !self.install_legacy_snapshot(&id, generation, detail) {
3469	                        return;
3470	                    }
3471	                    self.status.set("legacy sync".into());
3472	                    self.connect();
3473	                    return;
3474	                }
3475	                None => {
3476	                    // A new daemon can transiently expose the revision before
3477	                    // its journal snapshot is ready. Retry rather than silently
3478	                    // downgrading exactness on the first observation.
3479	                    if attempt + 1 == PROJECTION_RETRIES {
3480	                        if !self.install_legacy_snapshot(&id, generation, detail) {
3481	                            return;
3482	                        }
3483	                        self.status.set("legacy sync".into());
3484	                        self.connect();
3485	                        return;
3486	                    }
3487	                }
3488	            }
3489	            gloo_timers::future::TimeoutFuture::new(75).await;
3490	        }
3491	    }
