3493	    fn install_legacy_snapshot(&self, id: &str, generation: u64, detail: SessionDetail) -> bool {
3494	        if !self.projection_generation_is_current(id, generation) {
3495	            return false;
3496	        }
3497	        let (turns, pinned) =
3498	            turns_from_session_transcript(detail.transcript, &detail.tool_context);
3499	        batch(|| {
3500	            self.session_title.set(detail.title);
3501	            if let Some(root) = detail
3502	                .workspace_root
3503	                .or(detail.cwd)
3504	                .filter(|root| !root.is_empty())
3505	            {
3506	                self.cwd.set(root);
3507	            }
3508	            if !detail.model.is_empty() {
3509	                self.model.set(Some(detail.model));
3510	            }
3511	            self.turns.set(turns);
3512	            self.pinned_widgets.set(pinned);
3513	            self.active_decision_token.set(None);
3514	        });
3515	        true
3516	    }
