3518	    fn install_projection_snapshot(
3519	        &self,
3520	        id: &str,
3521	        generation: u64,
3522	        prepared: PreparedProjection,
3523	    ) -> bool {
3524	        if !self.projection_generation_is_current(id, generation) {
3525	            return false;
3526	        }
3527	        let active = prepared.active_turn.as_ref().and_then(|event| match event {
3528	            AgentEvent::TurnStarted { turn_id, model, .. } => {
3529	                Some((turn_id.clone(), model.clone()))
3530	            }
3531	            _ => None,
3532	        });
3533	        let terminal_turn_id = prepared
3534	            .last_turn_finished
3535	            .as_ref()
3536	            .and_then(|event| match event {
3537	                AgentEvent::TurnFinished { turn_id, .. } => Some(turn_id.as_str()),
3538	                _ => None,
3539	            });
3540	        let current_turn_id = active
3541	            .as_ref()
3542	            .map(|(turn_id, _)| turn_id.as_str())
3543	            .or(terminal_turn_id);
3544	        let rerouted = prepared
3545	            .model_rerouted
3546	            .as_ref()
3547	            .and_then(|event| match event {
3548	                AgentEvent::ModelRerouted {
3549	                    turn_id, effective, ..
3550	                } if Some(turn_id.as_str()) == current_turn_id => Some(effective.clone()),
3551	                _ => None,
3552	            });
3553	        let terminal_status = prepared
3554	            .last_turn_finished
3555	            .as_ref()
3556	            .and_then(|event| match event {
3557	                AgentEvent::TurnFinished { status, error, .. } if active.is_none() => {
3558	                    Some(match error {
3559	                        Some(error) => {
3560	                            let concise = format!("turn failed: {}", concise_error(error));
3561	                            (concise.clone(), Some((concise, error.clone())))
3562	                        }
3563	                        None if status != "completed" => (format!("turn {status}"), None),
3564	                        None => ("projection sync".into(), None),
3565	                    })
3566	                }
3567	                _ => None,
3568	            });
3569	        let last_stats = prepared
3570	            .last_turn_finished
3571	            .as_ref()
3572	            .and_then(|event| match event {
3573	                AgentEvent::TurnFinished {
3574	                    input_tokens,
3575	                    output_tokens,
3576	                    cache_read_tokens,
3577	                    tokens_per_second,
3578	                    ..
3579	                } => Some(TokenStats {
3580	                    input: input_tokens.unwrap_or(0),
3581	                    output: output_tokens.unwrap_or(0),
3582	                    cache_read: cache_read_tokens.unwrap_or(0),
3583	                    tokens_per_second: tokens_per_second.unwrap_or(0.0),
3584	                }),
3585	                _ => None,
3586	            });
3587	        let root = prepared.detail.workspace_root.or(prepared.detail.cwd);
3588	        let detail_model = prepared.detail.model;
3589	        batch(|| {
3590	            self.session_title.set(prepared.detail.title);
3591	            if let Some(root) = root.filter(|root| !root.is_empty()) {
3592	                self.cwd.set(root);
3593	            }
3594	            self.turns.set(prepared.turns);
3595	            self.pinned_widgets.set(prepared.pinned);
3596	            self.pending_permissions.set(prepared.permissions);
3597	            // Snapshot permission cards are visibility only; authority belongs
3598	            // only to a locally submitted turn's secret.
3599	            self.active_decision_token.set(None);
3600	            self.browser_active.set(prepared.browser_active);
3601	            self.active_turn_id
3602	                .set(active.as_ref().map(|(id, _)| id.clone()));
3603	            self.streaming.set(active.is_some());
3604	            self.last_turn_tokens.set(last_stats);
3605	            if let Some(model) = rerouted
3606	                .or_else(|| active.and_then(|(_, model)| model))
3607	                .or_else(|| (!detail_model.is_empty()).then_some(detail_model))
3608	            {
3609	                self.model.set(Some(model));
3610	            }
3611	            let (status, detail) =
3612	                terminal_status.unwrap_or_else(|| ("projection sync".to_string(), None));
3613	            self.status.set(status);
3614	            self.status_detail.set(detail);
3615	        });
3616	        // Open tails only after the atomic snapshot install has completed.
3617	        self.connect_projection_tail(
3618	            id.to_string(),
3619	            generation,
3620	            prepared.cursor,
3621	            prepared.lease_id,
3622	        );
3623	        self.connect_canvas_tail(id.to_string(), generation);
3624	        true
3625	    }
