3627	    fn connect_projection_tail(
3628	        &self,
3629	        id: String,
3630	        generation: u64,
3631	        initial_cursor: String,
3632	        lease_id: String,
3633	    ) {
3634	        let daemon = self.clone();
3635	        spawn_local(async move {
3636	            if !daemon.projection_generation_is_current(&id, generation) {
3637	                return;
3638	            }
3639	            let encode = |value: &str| {
3640	                js_sys::encode_uri_component(value)
3641	                    .as_string()
3642	                    .unwrap_or_else(|| value.to_string())
3643	            };
3644	            let events_url = format!(
3645	                "{}/v1/agent/projection/events?session_id={}&after_cursor={}&lease_id={}",
3646	                daemon.url.get_untracked().trim_end_matches('/'),
3647	                encode(&id),
3648	                encode(&initial_cursor),
3649	                encode(&lease_id),
3650	            );
3651	            let mut source = match EventSource::new(&events_url) {
3652	                Ok(source) => source,
3653	                Err(error) => {
3654	                    daemon.restart_projection(
3655	                        &id,
3656	                        generation,
3657	                        &format!("tail open failed: {error}"),
3658	                    );
3659	                    return;
3660	                }
3661	            };
3662	            let projection_events = match source.subscribe("session_projection") {
3663	                Ok(stream) => stream,
3664	                Err(error) => {
3665	                    daemon.restart_projection(
3666	                        &id,
3667	                        generation,
3668	                        &format!("tail subscribe failed: {error}"),
3669	                    );
3670	                    return;
3671	                }
3672	            };
3673	            let projection_resets = match source.subscribe("projection_reset") {
3674	                Ok(stream) => stream,
3675	                Err(error) => {
3676	                    daemon.restart_projection(
3677	                        &id,
3678	                        generation,
3679	                        &format!("reset subscribe failed: {error}"),
3680	                    );
3681	                    return;
3682	                }
3683	            };
3684	            // Store while CONNECTING. The browser owns reconnect and sends its
3685	            // Last-Event-ID; replacing this generation explicitly closes it.
3686	            {
3687	                let mut sources = daemon.planner_stream_sources.borrow_mut();
3688	                if sources.session_id != id || sources.generation != generation {
3689	                    return;
3690	                }
3691	                sources.projection = Some(source.clone());
3692	            }
3693	            let mut cursor = initial_cursor;
3694	            let mut stream = futures_util::stream::select(projection_events, projection_resets);
3695	            while let Some(message) = stream.next().await {
3696	                if !daemon.projection_generation_is_current(&id, generation) {
3697	                    return;
3698	                }
3699	                let Ok((event_name, message)) = message else {
3700	                    // gloo-net suppresses transient CONNECTING errors; an error
3701	                    // delivered here is terminal, so a new GET/lease is needed.
3702	                    daemon.restart_projection(&id, generation, "projection tail closed");
3703	                    return;
3704	                };
3705	                if event_name == "projection_reset" {
3706	                    daemon.restart_projection(&id, generation, "daemon projection reset");
3707	                    return;
3708	                }
3709	                let Some(data) = message.data().as_string() else {
3710	                    daemon.restart_projection(&id, generation, "projection frame missing data");
3711	                    return;
3712	                };
3713	                let frame = match serde_json::from_str::<SessionProjectionFrame>(&data) {
3714	                    Ok(frame) => frame,
3715	                    Err(_) => {
3716	                        daemon.restart_projection(
3717	                            &id,
3718	                            generation,
3719	                            "projection frame decode mismatch",
3720	                        );
3721	                        return;
3722	                    }
3723	                };
3724	                match projection_cursor_transition(&cursor, &frame.cursor) {
3725	                    CursorTransition::Duplicate => continue,
3726	                    CursorTransition::Reset => {
3727	                        daemon.restart_projection(
3728	                            &id,
3729	                            generation,
3730	                            "projection cursor gap or prefix change",
3731	                        );
3732	                        return;
3733	                    }
3734	                    CursorTransition::Next => {}
3735	                }
3736	                match frame.source {
3737	                    SessionProjectionSource::Agent => {
3738	                        let event = match serde_json::from_value::<AgentEvent>(frame.event) {
3739	                            Ok(event) if event.session_id() == Some(id.as_str()) => event,
3740	                            _ => {
3741	                                daemon.restart_projection(
3742	                                    &id,
3743	                                    generation,
3744	                                    "agent frame session/decode mismatch",
3745	                                );
3746	                                return;
3747	                            }
3748	                        };
3749	                        apply_event(
3750	                            &event,
3751	                            daemon.turns,
3752	                            daemon.session_id,
3753	                            daemon.streaming,
3754	                            daemon.status,
3755	                            daemon.status_detail,
3756	                            daemon.last_turn_tokens,
3757	                            daemon.session_tokens,
3758	                            daemon.model,
3759	                            daemon.active_turn_id,
3760	                            daemon.browser_active,
3761	                            daemon.browser_last_action,
3762	                            daemon.canvas_patches,
3763	                            daemon.pinned_widgets,
3764	                            daemon.awaiting_session_adoption,
3765	                            daemon.session_title,
3766	                            daemon.cwd,
3767	                        );
3768	                    }
3769	                    SessionProjectionSource::Control => {
3770	                        let event = match serde_json::from_value::<ControlEvent>(frame.event) {
3771	                            Ok(event) => event,
3772	                            Err(_) => {
3773	                                daemon.restart_projection(
3774	                                    &id,
3775	                                    generation,
3776	                                    "control frame decode mismatch",
3777	                                );
3778	                                return;
3779	                            }
3780	                        };
3781	                        daemon
3782	                            .permission_revision
3783	                            .update(|value| *value = value.wrapping_add(1));
3784	                        apply_control_event(&event, &id, daemon.pending_permissions);
3785	                    }
3786	                    SessionProjectionSource::Checkpoint => {
3787	                        let checkpoint = match serde_json::from_value::<SessionProjectionCheckpoint>(
3788	                            frame.event,
3789	                        ) {
3790	                            Ok(checkpoint) => checkpoint,
3791	                            Err(_) => {
3792	                                daemon.restart_projection(
3793	                                    &id,
3794	                                    generation,
3795	                                    "checkpoint decode mismatch",
3796	                                );
3797	                                return;
