6225	/// Pure decision helper: should we restore a persisted session on boot?
6226	/// Returns the session id if `persisted` is present and non-empty AND no
6227	/// session is already active. Testable off-wasm.
6228	fn should_restore_session<'a>(persisted: Option<&'a str>, active: Option<&str>) -> Option<&'a str> {
6229	    match persisted {
6230	        Some(id) if !id.is_empty() && active.is_none() => Some(id),
6231	        _ => None,
6232	    }
6233	}
