6235	/// Pre-flight fetch to verify a persisted session exists on the daemon, then
6236	/// restore via [`Daemon::switch_session`]. On failure (non-200, decode error,
6237	/// missing session) the persisted key is cleared and this returns `false` so
6238	/// the caller falls through to the normal boot path with state untouched.
6239	async fn restore_session_or_clear(daemon: &Daemon, id: &str) -> bool {
6240	    let url = daemon.url.get_untracked();
6241	    let get_url = format!("{}/v1/sessions/{id}", url.trim_end_matches('/'));
6242	    match Request::get(&get_url).send().await {
6243	        Ok(resp) => match resp.json::<SessionDetailResponse>().await {
6244	            Ok(r) if r.ok => {
6245	                if let Some(detail) = r.session {
6246	                    daemon.switch_session(detail.id, detail.title);
6247	                    return true;
6248	                }
6249	            }
6250	            Err(err) => {
6251	                log::error!("session restore decode error: {err}");
6252	            }
6253	            _ => {}
6254	        },
6255	        Err(err) => {
6256	            log::error!("session restore fetch error: {err}");
6257	        }
6258	    }
6259	    clear_persisted_session();
6260	    false
6261	}
